#include <omp.h>
#include <vector>
#include <cstddef>

int maxDegree(std::vector<int> const& A, size_t N) {
    int maxDeg = 0;

    // Parallelize over all vertices, each thread computes a row sum
    // and updates the global maximum using a reduction.
    #pragma omp parallel for reduction(max: maxDeg)
    for (size_t i = 0; i < N; ++i) {
        int deg = 0;
        for (size_t j = 0; j < N; ++j) {
            deg += A[i * N + j];   // adjacency matrix entry (i, j)
        }
        // For an undirected graph, row sum equals column sum.
        if (deg > maxDeg) maxDeg = deg;
    }

    return maxDeg;
}
